#!/usr/bin/env bash
# src/agentic/k8s/kctl.sh
# Reach a project's Kubernetes clusters through the kubeconfig `devbot init`
# generated for it. The generated file is named "<project>-<hash>.yaml" and its
# contexts come from the global `kubectl` catalogue, so neither is something a
# caller should have to reconstruct — that is what this command is for.
#
# Never use the plain ~/.kube/config for these clusters: its contexts are SSO
# exec contexts that expire, while the generated ones use the devbot profile.
#
# `exec` is the cluster-scoped form the `kctl-<cluster>` MCP servers call: the
# caller names the cluster and the context is applied for it, so a caller
# cannot reach another cluster's context through this wrapper.
set -euo pipefail

MODULE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=./functions.sh
source "${MODULE_DIR}/functions.sh"

_usage() {
  cat <<'EOF'
Usage:
  devbot kctl env      [path]   Print KUBECONFIG for the project (no credentials)
  devbot kctl contexts [path]   List the clusters this project may reach
  devbot kctl run      [path] -- <kubectl args...>
  devbot kctl exec     <cluster> [path] -- <kubectl args...>

`path` defaults to the current directory. The kubeconfig is generated by
`devbot init`; run `devbot reinit <path>` if it is missing.

The arguments after `--` are kubectl's own, not a command line that starts with
`kubectl` — this wrapper already prefixes the binary and the project's
kubeconfig:

  devbot kctl run . -- get ns default        ✔
  devbot kctl run . -- kubectl get ns default  ✘ (drop the leading `kubectl`)

`run` uses the kubeconfig's current-context unless you pass kubectl's own
`--context`. `exec` takes the cluster name from the catalogue and applies that
cluster's context itself — it is what the `kctl-<cluster>` MCP servers call, and
it refuses a caller `--context` so one cluster's server can never reach another.
EOF
}

# Resolve the generated files for a project. Sets PROJECT_DIR, PROJECT_CONFIG,
# READER, SPEC, SELECTION, KUBECONFIG_PATH and ENV_PATH.
_resolve() {
  local dir="${1:-.}" slug selection
  if [[ ! -d "${dir}" ]]; then
    _error "not a directory: ${dir}"
    return 1
  fi
  PROJECT_DIR="$(cd "${dir}" && pwd)"
  PROJECT_CONFIG="${PROJECT_DIR}/.devbot.project.jsonc"
  READER="${MODULE_DIR}/../../_shared/read_jsonc.py"

  if [[ ! -f "${PROJECT_CONFIG}" ]]; then
    _error "no ${PROJECT_CONFIG}; run: devbot init ${PROJECT_DIR}"
    return 1
  fi

  SPEC="$(python3 "${READER}" "$(_devbot_global_config)" kubectl 2>/dev/null || true)"
  if [[ -z "${SPEC}" || "${SPEC}" == "null" ]]; then
    _error "no 'kubectl' node in $(_devbot_global_config)"
    return 1
  fi

  selection="$(python3 "${READER}" "${PROJECT_CONFIG}" kubectl 2>/dev/null || true)"
  if [[ -z "${selection}" || "${selection}" == "null" ]]; then
    _error "${PROJECT_CONFIG} selects no clusters; add a 'kubectl' array"
    return 1
  fi

  slug="$(_project_slug)"
  KUBECONFIG_PATH="${HOME}/.kube/devbot/${slug}.yaml"

  if [[ ! -f "${KUBECONFIG_PATH}" ]]; then
    _error "no generated kubeconfig at ${KUBECONFIG_PATH}; run: devbot reinit ${PROJECT_DIR}"
    return 1
  fi
}

# Context names actually in the generated kubeconfig.
# init.sh skips clusters it cannot describe.
_generated_contexts() {
  kubectl --kubeconfig "${KUBECONFIG_PATH}" config get-contexts -o name
}

# The catalogue entry type behind a context: "eks" unless it says otherwise.
# A static cluster has no exec wrapper, so its credentials are never checked.
_catalogue_type() {
  jq -r --arg ctx "$1" '
    .clusters[]
    | (if ((.context // "") | test("^[A-Za-z0-9._-]+$")) then .context else .name end) as $c
    | select($c == $ctx)
    | (.type // "eks")' <<<"${SPEC}" 2>/dev/null | head -1
}

# The ${VAR} references in credential_env: the variables the
# wrapper reads, and therefore what the environment must set.
_credential_refs() {
  jq -r '.credential_env // {}
    | to_entries[]
    | .value
    | select(test("^\\$\\{[A-Za-z_][A-Za-z0-9_]*\\}$"))
    | sub("^\\$\\{"; "") | sub("\\}$"; "")' <<<"${SPEC}" \
    | sort -u | tr '\n' ' ' | sed 's/ $//'
}

# The catalogue entry behind a context, as "name<TAB>region". A context name
# defaults to the cluster name but a catalogue entry may override it, so match
# on the effective context name rather than assuming the two are equal.
_catalogue_entry() {
  jq -r --arg ctx "$1" '
    .clusters[]
    | (if ((.context // "") | test("^[A-Za-z0-9._-]+$")) then .context else .name end) as $c
    | select($c == $ctx)
    | [.name, .region] | @tsv' <<<"${SPEC}" 2>/dev/null | head -1
}

# The context a catalogue cluster name resolves to: its declared `context`, or
# the name itself when the entry declares none.
_catalogue_context() {
  jq -r --arg n "$1" '
    .clusters[]
    | select(.name == $n)
    | (if ((.context // "") | test("^[A-Za-z0-9._-]+$")) then .context else .name end)' \
    <<<"${SPEC}" 2>/dev/null | head -1
}

cmd_env() {
  _resolve "${1:-.}" || return 1
  local current refs cluster
  current="$(awk '/^current-context:/{print $2; exit}' "${KUBECONFIG_PATH}")"
  IFS=$'\t' read -r cluster _ < <(_catalogue_entry "${current}") || true
  refs="$(_credential_refs)"
  printf 'export KUBECONFIG=%q\n' "${KUBECONFIG_PATH}"
  # kubectl ignores this; informational only — named with its cluster, because
  # the context alone is what gets skimmed past.
  if [[ -n "${cluster:-}" ]]; then
    printf '# current-context: %s (%s)\n' "${current}" "${cluster}"
  else
    printf '# current-context: %s\n' "${current}"
  fi
  if [[ "$(_catalogue_type "${current}")" == "static" ]]; then
    printf '# credentials: none (static context)\n'
  else
    printf '# credentials: %s must be set in the environment\n' "${refs:-<none configured>}"
  fi
}

cmd_contexts() {
  _resolve "${1:-.}" || return 1
  if ! command -v kubectl >/dev/null 2>&1; then
    _error "kubectl is not on PATH"
    return 1
  fi

  local contexts ctx name region
  if ! contexts="$(_generated_contexts)"; then
    _error "could not read contexts from ${KUBECONFIG_PATH}"
    return 1
  fi

  printf '%-10s %-18s %s\n' "NAME" "CONTEXT" "REGION"
  while IFS= read -r ctx; do
    [[ -n "${ctx}" ]] || continue
    IFS=$'\t' read -r name region < <(_catalogue_entry "${ctx}") || true
    printf '%-10s %-18s %s\n' "${name:--}" "${ctx}" "${region:--}"
  done <<<"${contexts}"
}

# Refuse the kubectl flags that would replace what this wrapper resolved. A
# caller that can pass --kubeconfig, --server or --token is not bound by the
# project's kubeconfig at all, so the banner would name a target the command
# never used.
#
# Args: <refuse-context 0|1> <args...>
# --context is only refused when the caller's context is applied for it
# (`exec`), where a second --context would silently retarget the call.
_refuse_overrides() {
  local refuse_context="$1"
  shift

  local flag
  for flag in "$@"; do
    case "${flag}" in
      --context | --context=*)
        if [[ "${refuse_context}" -eq 1 ]]; then
          _error "refusing '${flag}': this server is bound to one cluster and applies its context"
          return 1
        fi
        ;;
      --kubeconfig | --kubeconfig=* | -s* | --server | --server=* | \
        --cluster | --cluster=* | --user | --user=* | \
        --token | --token=* | --as | --as=* | \
        --as-group | --as-group=* | --as-uid | --as-uid=* | \
        --username | --username=* | --password | --password=* | \
        --proxy-url | --proxy-url=* | --tls-server-name | --tls-server-name=* | \
        --client-certificate | --client-certificate=* | \
        --client-key | --client-key=* | \
        --certificate-authority | --certificate-authority=* | \
        --insecure-skip-tls-verify | --insecure-skip-tls-verify=*)
        _error "refusing '${flag}': it would override the project's kubeconfig"
        return 1
        ;;
    esac
  done
}

# Announce the target and verify what the exec wrapper will need at call time.
# The target goes to stderr, named with its catalogue cluster: the context alone
# (`gete-prod-ro`) is easy to skim past, and an answer read from the wrong
# cluster is reported as the other environment's until someone notices.
_preflight() {
  local current="$1" cluster
  IFS=$'\t' read -r cluster _ < <(_catalogue_entry "${current}") || true
  if [[ -n "${cluster:-}" ]]; then
    printf 'kubectl context: %s (%s)\n' "${current}" "${cluster}" >&2
  else
    printf 'kubectl context: %s\n' "${current}" >&2
  fi

  # The exec wrapper runs under `set -eu`: an unset credential
  # variable surfaces as an opaque plugin error, so check first.
  # A static context has no exec wrapper, so it must not require the AWS
  # variables at all — a static-only project renders and runs without them.
  if [[ "$(_catalogue_type "${current}")" != "static" ]]; then
    local key ref var
    while IFS=$'\t' read -r key ref; do
      [[ -n "${key}" ]] || continue
      [[ "${ref}" == '${'*'}' ]] || continue
      var="${ref#\$\{}"
      var="${var%\}}"
      if [[ -z "${!var:-}" ]]; then
        _error "${var} is not set; it backs ${key} in the global credential_env"
        return 1
      fi
    done < <(jq -r '.credential_env // {} | to_entries[] | "\(.key)\t\(.value)"' <<<"${SPEC}")
  fi
}

cmd_run() {
  local project="."
  if [[ "${1:-}" != "--" && $# -gt 0 ]]; then
    project="$1"
    shift
  fi
  [[ "${1:-}" == "--" ]] && shift

  # Fails before resolving anything: a wrapper run with the binary repeated is
  # the most common mistake (two sessions misread kubectl's "flags cannot be
  # placed before plugin name: --kubeconfig" — it names neither the wrapper nor
  # the fix — as a broken wrapper and exported KUBECONFIG by hand instead).
  if [[ "${1:-}" == "kubectl" || "${1:-}" == "k" ]]; then
    _error "'$1' is a kubectl client this wrapper already runs — drop the leading '$1': devbot kctl run <path> -- get ns default"
    return 1
  fi

  _resolve "${project}" || return 1

  if ! command -v kubectl >/dev/null 2>&1; then
    _error "kubectl is not on PATH"
    return 1
  fi

  _refuse_overrides 0 "$@" || return 1

  local current i
  current="$(awk '/^current-context:/{print $2; exit}' "${KUBECONFIG_PATH}")"
  local -a args=("$@")
  for ((i = 0; i < ${#args[@]}; i++)); do
    case "${args[i]}" in
      --context=*) current="${args[i]#--context=}" ;;
      --context) current="${args[i + 1]:-${current}}" ;;
    esac
  done
  _preflight "${current}" || return 1

  # Credentials come from credential_env at exec time.
  # The .env carries only KUBECONFIG.
  exec kubectl --kubeconfig "${KUBECONFIG_PATH}" "$@"
}

cmd_exec() {
  local cluster="${1:-}" project="."
  if [[ -z "${cluster}" ]]; then
    _error "usage: devbot kctl exec <cluster> [path] -- <kubectl args...>"
    return 1
  fi
  shift
  if [[ "${1:-}" != "--" && $# -gt 0 ]]; then
    project="$1"
    shift
  fi
  [[ "${1:-}" == "--" ]] && shift

  if [[ "${1:-}" == "kubectl" || "${1:-}" == "k" ]]; then
    _error "'$1' is a kubectl client this wrapper already runs — drop the leading '$1'"
    return 1
  fi

  _resolve "${project}" || return 1

  if ! command -v kubectl >/dev/null 2>&1; then
    _error "kubectl is not on PATH"
    return 1
  fi

  _refuse_overrides 1 "$@" || return 1

  # The catalogue decides the context; the generated file decides whether that
  # cluster is reachable at all. Rendering skips a cluster it cannot describe,
  # so "declared but missing here" must be refused by name — falling back to
  # another context is how a query meant for staging answers from production.
  local context
  context="$(_catalogue_context "${cluster}")"
  if [[ -z "${context}" ]]; then
    _error "cluster '${cluster}' is not in the global kubectl catalogue"
    return 1
  fi
  if ! _generated_contexts | grep -Fxq "${context}"; then
    _error "context '${context}' (cluster '${cluster}') is not in ${KUBECONFIG_PATH}; run: devbot reinit ${PROJECT_DIR}"
    return 1
  fi

  _preflight "${context}" || return 1

  exec kubectl --kubeconfig "${KUBECONFIG_PATH}" --context "${context}" "$@"
}

main() {
  local cmd="${1:-}"
  if [[ $# -gt 0 ]]; then
    shift
  fi

  case "${cmd}" in
    env)
      cmd_env "${1:-.}"
      ;;
    contexts)
      cmd_contexts "${1:-.}"
      ;;
    run)
      cmd_run "$@"
      ;;
    exec)
      cmd_exec "$@"
      ;;
    "")
      _usage >&2
      exit 1
      ;;
    -h|--help|help)
      _usage
      ;;
    *)
      _error "unknown 'kctl' subcommand: ${cmd}"
      _usage >&2
      exit 1
      ;;
  esac
}

main "$@"
